# check tails for padding
sb = json.load(open("storyboards.json"))
for k in sorted(sb):
    fr = sb[k]["frames"]
    dur = durs.get(k)
    tail = [f for f in fr if f[0] > dur - 1]
    print(k, sb[k]["label"], "dur", dur, "| frames beyond dur-1:", len(tail), "| last 3 frames:", fr[-3:])
